VIDEO = {'footer': 'Policy as Code  ·  Security Basics  ·  Java', 'poster': {'headline': [('POLICY', 'text'), ('AS CODE', 'accent')], 'taglines': [('A deny-by-default policy in Rego, tested, and its tests tested', 'gold')], 'before': {'code': 'c.securityContext.runAsNonRoot == false', 'note': 'A missing field is allowed', 'tag': 'BEFORE'}, 'after': {'code': 'not c.securityContext.runAsNonRoot == true', 'note': 'A missing field is denied', 'tag': 'AFTER'}}, 'highlight': {'console_green': ['AFTER THE FIX', 'THE RESULT', 'THE TESTS', 'FIRST, AS A WARNING'], 'console_rose': ['BEFORE THE FIX', 'THE ANSWER', 'THE RESPONSE', 'LATER, AS A DENIAL', 'THE SAME TRAP'], 'console_amber': ['HOW THE', 'HOW A MUTANT', 'WHICH MUTANTS', 'WHAT CONFTEST', 'A NEW RULE', 'THE DECISIONS'], 'console_cyan': ['THE RULES', 'THE REQUEST', 'THE FILES']}}
